{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration, which could lead to accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, which makes it difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration, which could lead to unnecessary storage costs and inefficient data management."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
  }, {})
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket                  = aws_s3_bucket.financials.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "financials" {
  bucket        = aws_s3_bucket.financials.id
  target_bucket = "${local.resource_prefix.value}-logs"
  target_prefix = "financials/"
}

resource "aws_s3_bucket_lifecycle_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id

  rule {
    id     = "expire-old-versions"
    status = "Enabled"

    noncurrent_version_expiration {
      days = 30
    }
  }

  rule {
    id     = "delete-old-objects"
    status = "Enabled"

    expiration {
      days = 365
    }
  }
}",
  "fix_summary": "Added a Public Access Block to prevent accidental public exposure, enabled access logging to track access patterns, and added a lifecycle configuration to manage object versions and storage costs efficiently."
}
